const bands=['6-8','9-11','12-14'];
const item=(id,category,title,question,tag,levels,bodies,source,url,related,kind='article')=>({id,category,title,question,tag,kind,minutes:kind==='wow'?1:3,words:[title,question,tag,category].join(' ').toLowerCase(),fact:levels[0].split('. ')[0]+'.',source,url,related,levels:Object.fromEntries(bands.map((b,i)=>[b,levels[i]])),sectionsByAge:Object.fromEntries(bands.map((b,i)=>[b,bodies[i]])),sections:bodies[1]});
export const newTopics=[
item('internet','tech','The internet is a team effort','How does the internet work?','Future Lab · Connections',
['The internet joins many computer networks. A message can travel through cables and wireless connections to reach another computer. It is not all stored inside your tablet!','The internet connects networks. Devices send information in small pieces called packets. Routers help these pieces travel, and software puts the useful information together at the destination.','The internet is a network of networks. Packets carry data and addressing information; routers forward them between networks. The web is one service using this infrastructure, alongside others such as email.'],
[[['A journey in pieces','Imagine a picture travelling in small envelopes. The device receiving it needs to put the pieces together. Real networks use agreed rules to communicate.'],['Try a paper network','Draw three houses and a library. Connect them with lines. Can you find two routes between a house and the library?']],[['A website needs a home','A server responds to a browser’s request. Your home Wi-Fi is one link in a much larger system. A Wi-Fi connection alone does not guarantee access to the wider internet.'],['Think about a missing link','If the classroom Wi-Fi works but a website does not, list two possible reasons. One observation is not enough to identify the cause.']],[['Layers have different jobs','Names, addresses, routing and application requests solve different problems. A broken website, a local Wi-Fi issue and an upstream connection failure can look similar to a user.'],['Design challenge','Draw the request path from a browser to a server. Mark which parts could still work if one link failed. Do not put real private network details in your drawing.']]],'MDN Web Docs','https://developer.mozilla.org/en-US/docs/Learn_web_development/Howto/Web_mechanics/How_does_the_Internet_work',['lunchbox-library','algorithms','online-safety']),
item('sensors','tech','How can a machine notice things?','What is a sensor?','Future Lab · Inventing',
['A sensor helps a machine notice something, like light, movement or temperature. A program can use that information to decide what happens next.','A sensor turns a physical change into a signal a machine can use. A light sensor can help a device respond to brightness. The program decides what to do with the reading.','Sensors measure aspects of the physical world and produce signals that a system can process. Readings depend on calibration, placement, range and conditions; a number is not automatically an accurate description of the environment.'],
[[['Notice and respond','Your eyes notice light. A device uses a different kind of detector. Neither the sensor nor the program needs to be a person.'],['Invent on paper','Draw a pretend lamp that turns on when a room becomes dark. Add arrows for “notice” and “respond”. Do not touch electrical fittings.']],[['Input, rule, output','In a simple automatic lamp, brightness is an input, a threshold is part of the rule, and switching a light is an output.'],['Test your idea','Would your lamp react to a shadow passing over its sensor? How could you avoid rapid switching? Think it through on paper.']],[['A measurement has limits','A processor’s temperature is not always the room’s air temperature. An accelerometer measures acceleration, including effects used to infer orientation; it is not a magical location tracker.'],['Ask a better question','For a garden-watering design, what would you measure, where would you measure it, and how would you test that the reading means what you think it means?']]],'micro:bit Educational Foundation','https://microbit.org/get-started/features/sensors/',['amani-rain','data','algorithms']),
item('data','tech','Numbers that tell a useful story','What is data?','Future Lab · Think clearly',
['Data is information we collect. You could count red, blue and green pencils. A clear question helps you know what to count.','Data can include counts, measurements, words and categories. To use it well, ask where it came from, what was measured and what might be missing.','Data represents observations or recorded information. Its usefulness depends on definitions, collection methods, missing values and context. A striking pattern is a reason to investigate, not automatic proof of a cause.'],
[[['Count something simple','Draw three red circles and two blue circles. Your drawing contains information you can count without collecting anyone’s private details.'],['Tell the story','Which colour appears more often in your drawing? Does that tell you what colour every child in Kenya likes? No: it describes your drawing.']],[['Choose a clear question','Counting books by colour answers a different question from counting them by topic. Decide what each category means before collecting information.'],['Look for what is missing','A survey of your reading club describes that group. It may not represent children who are not in the club.']],[['Association is not explanation','If two things change together, one may affect the other, or both may depend on another factor. Definitions and sampling choices can also create apparent patterns.'],['Challenge a claim','Someone says a class’s favourite subject proves all children prefer it. Explain why that conclusion reaches beyond the data collected.']]],'ZUNO original data-literacy lesson',null,['amani-rain','message-mystery','ai']),
item('online-safety','tech','Your pause-and-check toolkit','How can I stay safer online?','Future Lab · Digital kindness',
['Keep your private details private. If a message worries you or asks you to keep an uncomfortable secret, tell a trusted grown-up. You do not have to reply.','Pause before sharing a name, school, photo, location or password. Ask a trusted grown-up about confusing links or messages. If something upsetting happens, it is okay to stop and ask for help.','Think about what information a service needs, what it can reveal and who can access it. Use privacy settings with a parent or guardian. Pressure, secrecy or urgency in a message is a reason to pause, not proof that you must act.'],
[[['You can say no','You can leave a conversation or stop an activity. If someone is unkind or makes you uncomfortable, tell a grown-up you trust.'],['Practise a helpful sentence','Try saying: “I saw something online that made me uncomfortable. Can you help me?” You do not have to solve it alone.']],[['Check with someone you trust','A familiar-looking account or logo is not enough to prove a message is genuine. Do not test a suspicious link yourself.'],['Kindness belongs online too','Ask permission before sharing someone else’s picture. Being curious does not mean being entitled to another person’s private details.']],[['Consider the information trail','An image, background detail or repeated username can reveal more than the words in a post. Avoid sharing unnecessary personal context.'],['Respond without blame','If a friend has shared something worrying, help them reach a trusted adult. Do not circulate the material to prove what happened or shame them for a mistake.']]],'UNICEF','https://www.unicef.org/parenting/child-care/online-privacy',['message-mystery','internet','ai']),
item('electricity','science','The energy behind the switch','Where does electricity come from?','How things work · Energy',
['Electricity helps lights, fans and computers work. People can produce electrical energy using sunlight, moving water, wind and other energy sources. Never open a plug or put anything into a socket.','Electrical energy can be produced by converting other forms of energy. Many generators use motion, while solar cells can convert sunlight directly into electricity. Real electrical systems need trained people and safety protections.','Electricity is an energy carrier. Generation converts other forms of energy into electrical energy; it does not create energy from nothing. Different generation methods have different materials, environmental effects and operating constraints.'],
[[['A path matters','A simple circuit needs a complete path for current. You can explore a pretend circuit safely in Zuno’s on-screen lab.'],['Look, don’t dismantle','Name three things that use electricity. Keep plugs, cables and batteries closed and ask a grown-up about anything damaged.']],[['Generation and storage differ','A battery stores energy chemically and can supply electrical energy. It is not the same thing as a power station or a solar panel.'],['Try the virtual circuit','Change the resistance and voltage in the on-screen model. Its numbers describe an idealised resistor, not instructions for building a real circuit.']],[['A useful model has limits','The virtual lab uses Ohm’s law for an ideal resistor. Real components can heat up, change resistance and fail. The model is not a safety calculator.'],['Ask about the whole system','Generation, transmission, storage and demand all matter. Why might a useful energy source still require a larger system around it?']]],'U.S. Energy Information Administration','https://www.eia.gov/energyexplained/electricity/',['solar-energy','sun','algorithms']),
item('solar-energy','science','Can sunshine power a school?','How does solar electricity work?','Our future · Clean energy',
['Solar cells can turn sunlight into electricity. A school with solar panels still needs the right equipment and grown-ups trained to install it.','Solar photovoltaic cells convert sunlight directly into electricity. How much a system produces depends on conditions such as available sunlight and shading. Batteries, if included, can store some energy for later.','Photovoltaic cells use semiconductor materials to convert light into electrical energy. System output depends on irradiance, temperature, orientation, shading and other losses. Installed capacity is not the same as the energy produced over a day.'],
[[['A sunny idea','A panel cannot collect sunlight at night. A whole system may use stored energy or another electricity supply when sunlight is unavailable.'],['Design on paper','Draw a school and imagine where sunshine reaches it. This is a drawing activity: never climb onto a roof or touch installed panels.']],[['A shadow changes the question','A sunny climate alone does not tell you how much energy a particular roof system will produce. Nearby trees and buildings can cast shadows.'],['Think about the school day','List which devices need electricity and when. How might their needs differ from the times when sunlight is strongest?']],[['Match supply and demand','Energy planning needs a time profile, not just one attractive power rating. Storage adds cost, limits and losses, while a grid connection changes the options.'],['Make your assumptions visible','For a fictional school, state the sunlight, shading and device-use assumptions you would need before estimating a system. Do not treat the estimate as installation advice.']]],'U.S. Energy Information Administration','https://www.eia.gov/energyexplained/solar/',['electricity','sun','data'])
];
const wow=(...args)=>item(...args,'wow');
export const littleWows=[
wow('wow-venus','wows','A year before a full spin?','Can a planet’s full spin take longer than its year?','Little Wow · Space',
['Venus takes longer to turn all the way around once than to travel around the Sun once. What a slow spinner!','Venus completes one rotation in about 243 Earth days, but one orbit takes about 225. A spin and a trip around the Sun are different motions.','Venus’s sidereal rotation period is about 243 Earth days, longer than its roughly 225-day orbital period. Its sunrise-to-sunrise solar day is a different interval.'],
[[['Think about it','A spinning top can turn while travelling around a table. Those are two different movements.']],[['Try the idea','Imagine a toy that turns slowly while you carry it around a circle. Which movement decides its year?']],[['Keep the definition','Here “full spin” means rotation relative to distant stars. Calling every definition of a day 243 Earth days would be misleading.']]],'NASA Science','https://science.nasa.gov/venus/venus-facts/',['solar-system','sun']),
wow('wow-butterfly','wows','Tasting with your feet?','Can butterflies taste with their feet?','Little Wow · Nature',
['Some butterflies use sensors on their feet to check plants. Your feet cannot do that!','Butterflies have chemical sensors on their feet. A female can use them to help check whether a plant is suitable for laying eggs.','Contact chemoreceptors on butterflies’ feet detect plant chemicals. This can help females select host plants for their caterpillars; it is not simply the same as a human tasting a snack.'],
[[['A different toolkit','Animals notice the world in different ways. Watch butterflies without touching or catching them.']],[['Wonder a little more','Why might choosing the right plant matter for a caterpillar that will hatch there?']],[['Compare carefully','Similar words such as “taste” can describe related detection functions without implying the same anatomy or behaviour as a human.']]],'American Museum of Natural History','https://www.amnh.org/exhibitions/butterflies/butterfly-faq',['sensors','elephants']),
wow('wow-coral','wows','That reef is made by animals.','Is coral really an animal?','Little Wow · Ocean',
['Corals are animals. Many tiny coral polyps help build the hard structures that become reefs.','A coral may look like a colourful rock, but its living polyps are animals. Many reef-building corals make hard skeletons.','Reef-building coral colonies contain animal polyps that deposit calcium carbonate skeletons. Their plant-like appearance does not make them plants.'],
[[['Look closer','A living thing can look very different from the animals you meet on land.']],[['Keep wondering','What clues would you look for before deciding whether something is living?']],[['Avoid the shortcut','Appearance is a clue, not a classification system. Many corals also have important relationships with algae.']]],'NOAA Ocean Service','https://oceanservice.noaa.gov/facts/coral.html',['coral','water-cycle']),
wow('wow-sunlight','wows','Sunshine has travel time.','Does sunlight reach Earth instantly?','Little Wow · Space',
['Sunlight takes about eight minutes to travel from the Sun to Earth. Even light needs time for a journey that big.','Light travels very fast, but the Sun is far away. The trip from the Sun’s surface to Earth takes roughly eight minutes and twenty seconds.','At an average Earth–Sun distance of about one astronomical unit, light’s travel time is roughly 499 seconds. Distance varies, so this is an approximate value.'],
[[['Think big','Fast does not mean instant. Space contains enormous distances. Never look directly at the Sun.']],[['A useful question','If light came from farther away, would you expect its journey to take more time or less?']],[['Name the interval','This is travel through space from the solar surface to Earth. It is not the time energy takes to move from the Sun’s core to its surface.']]],'NASA Science','https://science.nasa.gov/sun/',['sun','solar-system']),
wow('wow-rainbow','wows','A rainbow can be a circle.','Is a rainbow always half a circle?','Little Wow · Light',
['A full rainbow is a circle. From the ground we usually see only part of it.','Sunlight and water drops can make a circular rainbow. The ground often hides the lower part from our view.','Rainbow geometry depends on the observer, the light and droplets. From suitable elevated viewpoints, the full circle can be visible; the familiar bow is only part of the pattern.'],
[[['Wonder safely','Enjoy rainbows from a safe place. Never climb or lean out to look for a full circle.']],[['Notice your viewpoint','How could changing where you stand change which part of a pattern you can see?']],[['No fixed rainbow object','Different observers receive light from different droplets. A rainbow is an optical phenomenon, not a coloured arch you can walk up to.']]],'NOAA NESDIS','https://www.nesdis.noaa.gov/about/k-12-education/optical-phenomena/what-causes-rainbow',['water-cycle','patterns']),
wow('wow-packets','wows','A message can travel in pieces.','Does an internet message always travel as one piece?','Little Wow · Tech',
['A digital message can be split into small pieces for its journey. Computers use rules to handle the pieces.','Information on the internet travels in packets. Network protocols help devices send and make sense of the data.','Packet-switched networks forward addressed chunks of data. Delivery order and reliability are handled differently by different protocols, so the “little envelopes” comparison has limits.'],
[[['A paper idea','Imagine sending a drawing in numbered pieces. Why might the numbers help?']],[['Ask a designer’s question','What could a system do if a needed piece did not arrive?']],[['Check the analogy','Not every packet is guaranteed to arrive or follow the same route. A friendly analogy should not hide important limits.']]],'MDN Web Docs','https://developer.mozilla.org/en-US/docs/Learn_web_development/Getting_started/Web_standards/How_the_web_works',['internet','lunchbox-library']),
wow('wow-trunk','wows','A nose that can pick things up.','Is an elephant’s trunk just a long nose?','Little Wow · Wildlife',
['An elephant’s trunk is its nose and upper lip combined. It can smell and pick up things too.','An elephant uses its trunk for breathing, smelling, handling food and other tasks. It is a flexible combination of nose and upper lip.','The elephant trunk is a muscular hydrostat, combining fine manipulation and strength without a bony internal support. One structure serves many functions.'],
[[['Many jobs','Think of another body part that helps an animal do more than one thing.']],[['Observe, don’t approach','Watch wildlife only from a safe distance with a qualified guide. A clever adaptation is not an invitation to touch.']],[['A design question','What trade-offs might an engineer face when trying to combine flexibility, strength and precise control?']]],'WWF','https://www.worldwildlife.org/species/african-elephant',['elephants','sensors']),
wow('wow-bugs','wows','A mistake can be a clue.','What is debugging?','Little Wow · Tech',
['When code does the wrong thing, finding and fixing the problem is called debugging. A mistake can teach you something.','Debugging means investigating why a program behaves differently from what you intended. Clear predictions and small changes help.','Debugging compares expected and observed behaviour to identify causes. A successful rerun is useful evidence, but one test does not prove a program works in every situation.'],
[[['Give it a go','Tell a pretend robot to move right, then up. What happens if you swap the order?']],[['Try the habit','Before changing code, write down what you expect each step to do.']],[['Look beyond the happy path','Test an edge case such as a blocked route or an unexpected starting position. What assumption does it reveal?']]],'ZUNO original computing lesson',null,['nia-robot','algorithms','data'])
];
